    minItems: 0,
    maxItems: null,
    reorderAction: null,
    deleteAction: null,
    reorderSuccessMessage: Craft.t('app', 'New order saved.'),
    reorderFailMessage: Craft.t('app', 'Couldn’t save new order.'),
    confirmDeleteMessage: Craft.t('app', 'Are you sure you want to delete “{name}”?'),
