        strokeWidth: 2,
        stroke: this.settings.colors.white,
        originX: 'center',
        originY: 'center',
        width: gridWidth,
        height: gridHeight,
        left: gridWidth / 2,
        top: gridHeight / 2,
        fill: 'rgba(255,255,255,0)'
