    const height = this.clipper.height;
    this.rectangleHasFocusOutline = false;
    const rectangleOptions = {
      fill: this.settings.colors.transparent,
      top: 0,
      left: 0,
      strokeWidth: strokeWidth,
      originX: 'center',
      originY: 'center'
    };
