        [param('staticLayoutElements')]: this.settings.staticLayoutElements,
        [param('elementType')]: 'CraftCms\\Cms\\Field\\Elements\\ContentBlock',
        [param('ownerId')]: elementEditor?.getDraftElementId(this.settings.ownerId) ?? this.settings.ownerId,
